cd /workspace && cat > src/ledger.ts <<'EOF'
export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  private readonly seen = new Map<string, Receipt>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    if (typeof tenant !== 'string' || typeof key !== 'string' || !tenant || !key
      || !Number.isInteger(cents) || cents <= 0) throw new Error('invalid payment');
    // Check-and-insert happens synchronously, so concurrent calls cannot both debit.
    const id = JSON.stringify([tenant, key]);
    const existing = this.seen.get(id);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    this.seen.set(id, receipt);
    return receipt;
  }
}
EOF
cat > src/service.ts <<'EOF'
import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';
export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}
  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    if (typeof tenant !== 'string' || typeof key !== 'string' || !tenant || !key
      || !Number.isInteger(cents) || cents <= 0
      || !Number.isInteger(attempts) || attempts < 1 || attempts > 5) throw new Error('invalid payment');
    // Debit once (idempotent per tenant/key); retries only re-send the acknowledgement.
    const receipt = await this.ledger.apply(tenant, key, cents);
    for (let n = 1; ; n++) {
      try {
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        if (!(error instanceof Transient) || n >= attempts) throw error;
      }
    }
  }
}
EOF
cat > checks/retry.cjs <<'EOF'
const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');
async function main() {
  const ledger = new Ledger(); const seen = []; let fail = 2;
  const s = new PaymentService(ledger, { acknowledge: async r => { seen.push(r); if (fail-- > 0) throw new Transient('t'); } });
  const r = await s.pay('a', 'k', 5);
  assert.equal(ledger.entries.length, 1); assert.equal(seen.length, 3); assert(seen.every(x => x === r));
  assert.equal(await s.pay('a', 'k', 5), r); assert.equal(ledger.entries.length, 1);
  await assert.rejects(s.pay('a', 'k', 6), /key conflict/);
  await s.pay('b', 'k', 6); assert.equal(ledger.entries.length, 2);
  const l2 = new Ledger(); const s2 = new PaymentService(l2, { acknowledge: async () => {} });
  const rs = await Promise.all([s2.pay('t', 'k', 1), s2.pay('t', 'k', 1)]);
  assert.equal(rs[0], rs[1]); assert.equal(l2.entries.length, 1);
  const e = new Transient('last'); let calls = 0;
  const s3 = new PaymentService(new Ledger(), { acknowledge: async () => { calls++; throw e; } });
  await assert.rejects(s3.pay('t', 'k', 1, 2), x => x === e); assert.equal(calls, 2);
  calls = 0; const o = new Error('other');
  const s4 = new PaymentService(new Ledger(), { acknowledge: async () => { calls++; throw o; } });
  await assert.rejects(s4.pay('t', 'k', 1), x => x === o); assert.equal(calls, 1);
  const l5 = new Ledger(); const s5 = new PaymentService(l5, { acknowledge: async () => { calls++; } }); calls = 0;
  for (const a of [0, 6, 1.5, NaN]) await assert.rejects(s5.pay('t', 'k', 1, a), /invalid payment/);
  await assert.rejects(s5.pay('', 'k', 1), /invalid payment/);
  assert.equal(l5.entries.length, 0); assert.equal(calls, 0);
}
module.exports = main();
EOF
tsc -p tsconfig.json && node checks/public.cjs && node checks/retry.cjs && echo OK

